import assert from "node:assert/strict";
import { decide } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-g2-3/bot.mjs";

const c = (over = {}) => ({ userId: "u1", category: "marketing", timezone: "Europe/Istanbul", quietStart: "22:00", quietEnd: "07:30", ...over });
const at = (iso) => new Date(iso);

// Transactional: always sends, ignores quiet hours and cap, rule null.
for (let i = 0; i < 5; i++) assert.deepEqual(decide(c({ userId: "t1", category: "transactional" }), at("2026-10-23T23:00:00Z")), { send: true, rule: null });

// Marketing: 3 sends, 4th blocked by daily-cap. Istanbul 12:00 = 09:00Z (not quiet).
const noon = at("2026-10-23T09:00:00Z");
assert.deepEqual(decide(c({ userId: "m1" }), noon), { send: true, rule: null });
assert.deepEqual(decide(c({ userId: "m1" }), noon), { send: true, rule: null });
assert.deepEqual(decide(c({ userId: "m1" }), noon), { send: true, rule: null });
assert.deepEqual(decide(c({ userId: "m1" }), noon), { send: false, rule: "daily-cap" });

// Transactional after cap still sends.
assert.deepEqual(decide(c({ userId: "m1", category: "transactional" }), noon), { send: true, rule: null });

// Local day boundary: 2026-10-23T21:30Z is 00:30 on 10-24 in Istanbul -> new cap bucket.
assert.deepEqual(decide(c({ userId: "m1" }), at("2026-10-23T21:30:00Z")), { send: true, rule: null });
// Same UTC day, but still 10-23 in Istanbul at 20:59Z? 20:59Z = 23:59 Istanbul -> still capped day 10-23.
assert.deepEqual(decide(c({ userId: "m1" }), at("2026-10-23T20:59:00Z")), { send: false, rule: "quiet-hours" });

// Quiet hours wrap past midnight (22:00-07:30 Istanbul). Marketing blocked, not counted.
assert.deepEqual(decide(c({ userId: "q1" }), at("2026-10-23T20:00:00Z")), { send: false, rule: "quiet-hours" }); // 23:00 local
assert.deepEqual(decide(c({ userId: "q1" }), at("2026-10-23T04:00:00Z")), { send: false, rule: "quiet-hours" }); // 07:00 local
assert.deepEqual(decide(c({ userId: "q1" }), at("2026-10-23T04:30:00Z")), { send: true, rule: null });          // 07:30 local, end exclusive
assert.deepEqual(decide(c({ userId: "q1" }), at("2026-10-23T19:00:00Z")), { send: true, rule: null });          // 22:00 local start inclusive? see next
EOF
echo written

cat > /tmp/bot-test/check.mjs <<'EOF'
import assert from "node:assert/strict";
import { decide } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-g2-3/bot.mjs";

const NO_QUIET = { quietStart: "00:00", quietEnd: "00:00" };
const c = (over = {}) => ({ userId: "u1", category: "marketing", timezone: "Europe/Istanbul", quietStart: "22:00", quietEnd: "07:30", ...over });
const at = (iso) => new Date(iso);
const SEND = { send: true, rule: null };
const CAP = { send: false, rule: "daily-cap" };
const QUIET = { send: false, rule: "quiet-hours" };

// 1. Transactional: always sends, ignores quiet hours and cap.
for (let i = 0; i < 5; i++) assert.deepEqual(decide(c({ userId: "t1", category: "transactional" }), at("2026-10-23T20:00:00Z")), SEND); // 23:00 local, quiet

// 2. Marketing cap: 3 sends then daily-cap. 09:00Z = 12:00 Istanbul, not quiet.
const noon = at("2026-10-23T09:00:00Z");
assert.deepEqual(decide(c({ userId: "m1" }), noon), SEND);
assert.deepEqual(decide(c({ userId: "m1" }), noon), SEND);
assert.deepEqual(decide(c({ userId: "m1" }), noon), SEND);
assert.deepEqual(decide(c({ userId: "m1" }), noon), CAP);
assert.deepEqual(decide(c({ userId: "m1", category: "transactional" }), noon), SEND); // still sends after cap

// 3. Local day boundary, quiet window disabled. 20:59Z = 23:59 local 10-23; 21:00Z = 00:00 local 10-24.
const b = { userId: "d1", ...NO_QUIET };
assert.deepEqual(decide(c({ ...b }), at("2026-10-23T20:59:00Z")), SEND);
assert.deepEqual(decide(c({ ...b }), at("2026-10-23T20:59:30Z")), SEND);
assert.deepEqual(decide(c({ ...b }), at("2026-10-23T20:59:45Z")), SEND);
assert.deepEqual(decide(c({ ...b }), at("2026-10-23T20:59:50Z")), CAP); // 4th on local 10-23
assert.deepEqual(decide(c({ ...b }), at("2026-10-23T21:00:00Z")), SEND); // local 10-24, new bucket

// 4. Quiet window wraps midnight: 22:00-07:30 local (Istanbul = UTC+3).
assert.deepEqual(decide(c({ userId: "q1" }), at("2026-10-23T19:00:00Z")), QUIET); // 22:00 local, start inclusive
assert.deepEqual(decide(c({ userId: "q1" }), at("2026-10-23T20:00:00Z")), QUIET); // 23:00
assert.deepEqual(decide(c({ userId: "q1" }), at("2026-10-23T21:30:00Z")), QUIET); // 00:30
assert.deepEqual(decide(c({ userId: "q1" }), at("2026-10-23T04:00:00Z")), QUIET); // 07:00
assert.deepEqual(decide(c({ userId: "q1" }), at("2026-10-23T04:30:00Z")), SEND);  // 07:30 end exclusive
assert.deepEqual(decide(c({ userId: "q1" }), at("2026-10-23T18:59:00Z")), SEND);  // 21:59 local

// 5. Quiet-blocked marketing is not counted: quiet hour then 3 daytime sends still all allowed.
const q2 = { userId: "q2" };
decide(c({ ...q2 }), at("2026-10-23T20:00:00Z")); // quiet
decide(c({ ...q2 }), at("2026-10-23T20:00:00Z")); // quiet
decide(c({ ...q2 }), at("2026-10-23T20:00:00Z")); // quiet
decide(c({ ...q2 }), at("2026-10-23T20:00:00Z")); // quiet
assert.deepEqual(decide(c({ ...q2 }), noon), SEND);
assert.deepEqual(decide(c({ ...q2 }), noon), SEND);
assert.deepEqual(decide(c({ ...q2 }), noon), SEND);
assert.deepEqual(decide(c({ ...q2 }), noon), CAP);

// 6. Non-wrapping window and empty window (start === end).
const day = { userId: "w1", timezone: "UTC", quietStart: "13:00", quietEnd: "14:00" };
assert.deepEqual(decide({ ...day }, at("2026-10-23T13:30:00Z")), QUIET);
assert.deepEqual(decide({ ...day }, at("2026-10-23T14:00:00Z")), SEND);
assert.deepEqual(decide({ ...day, userId: "w2", quietStart: "09:00", quietEnd: "09:00" }, at("2026-10-23T09:00:00Z")), SEND);

// 7. Per-customer timezone, not server clock: New York 23:30 local on 10-22 = 03:30Z 10-23.
const ny = { userId: "ny1", timezone: "America/New_York", ...NO_QUIET };
for (let i = 0; i < 3; i++) assert.deepEqual(decide({ ...ny }, at("2026-10-23T03:30:00Z")), SEND);
assert.deepEqual(decide({ ...ny }, at("2026-10-23T03:31:00Z")), CAP);   // still local 10-22
assert.deepEqual(decide({ ...ny }, at("2026-10-23T04:00:00Z")), SEND);  // local 10-23 00:00

// 8. Invalid input throws.
assert.throws(() => decide(c({ category: "promo" }), noon), TypeError);
assert.throws(() => decide(c({ quietStart: "24:00" }), noon), TypeError);
assert.throws(() => decide(c({ quietEnd: "7:30" }), noon), TypeError);
assert.throws(() => decide(c({ timezone: "Mars/Olympus" }), noon), RangeError);
assert.throws(() => decide(c(), new Date("nope")), TypeError);

// 9. Memory stays bounded: 10 days of sends for one user keep only today and yesterday.
const big = { userId: "mem" , ...NO_QUIET, timezone: "UTC"};
for (let d = 1; d <= 10; d++) {
  decide({ ...big }, at(`2026-10-${String(d).padStart(2, "0")}T12:00:00Z`));
}
// Repeat-call check on day 10 reaches cap, proving counts work after pruning.
decide({ ...big }, at("2026-10-10T12:00:00Z"));
decide({ ...big }, at("2026-10-10T12:00:00Z"));
assert.deepEqual(decide({ ...big }, at("2026-10-10T12:00:00Z")), CAP);

console.log("all checks passed");
EOF
